#[path="../../research/sources/backend/vb_ast_backend.rs"] mod backend;
#[path="../src/addressing.rs"] mod addressing;
#[path="../src/conversions.rs"] mod conversions;
#[path="../src/tables.rs"] mod tables;
use backend::residual::Vm;
fn fixture()->Vm{let mut v=Vm::new().unwrap();v.memory.map(0x20000000,vec![0;131072]).unwrap();v.memory.map(0x30000000,vec![0;65536]).unwrap();v.set_register("ESP",0x3000f000).unwrap();v.memory.write_u32(0x20000000,0x20000100).unwrap();v.memory.write_u32(0x20000100,0x20010000).unwrap();v.memory.write(0x2000010e,2,65535).unwrap();v}
fn bytes(v:&Vm,a:u32,n:usize)->Vec<u8>{(0..n).map(|j|v.memory.read(a+j as u32,1).unwrap() as u8).collect()}
fn encoded(op:u16,payload:&[u8])->Vec<u8>{let mut b=tables::encode_opcode(op).unwrap();b.extend_from_slice(payload);b}
fn compare(v:Vm,entry:u32,args:&[u32],actual:Vec<u8>,name:&str){let before=bytes(&v,0x20000200,128);let mut b=backend::Backend::new(v,backend::residual::NoHost);b.rust_enabled=false;b.call(entry,args,0x20000000).unwrap_or_else(|e|panic!("oracle failure {name}: {e:?}"));if entry==0x0fac31c9{assert_eq!(b.vm.get_register("EAX").unwrap(),1,"native optimization return {name}");}assert_eq!(b.vm.get_register("ESP").unwrap(),0x3000f000,"stack balance {name}");let len=b.vm.memory.read(0x2000010c,2).unwrap() as usize;let expected=bytes(&b.vm,0x20010000,len);assert_eq!(actual,expected,"{name}");assert_eq!(actual.len(),len,"offset {name}");assert_eq!(before,bytes(&b.vm,0x20000200,128),"descriptor/AST state {name}");assert_eq!(b.vm.memory.read(0x2000010e,2).unwrap(),65535,"capacity {name}");assert_eq!(b.vm.memory.read(0x20000000,4).unwrap(),0x20000100,"context {name}");}
fn main(){let base=fixture();let mut n=0;for kind in 1..=12{for mode in 1..=6{for ty in [5,6,8,10,11,12,13,15,16,22]{for flags in [0,0x1000,0x8000,0x40]{for descflag in [0,1]{let mut v=base.clone();let desc=0x20000200;v.memory.write_u32(desc,kind).unwrap();for(off,val)in [(6,descflag),(8,8),(10,10),(12,12)]{v.memory.write(desc+off,2,val).unwrap();}let raw=v.memory.read(0x0faaa670+u32::from(ty)*4,4).unwrap() as i32;let idx=((((( !flags as u32>>12)&1)as i32-12)+raw*2)*2)+((!flags as u32>>11)&1) as i32;let lookup=0x0fac29d8u32.wrapping_add(idx as u32);let meta=addressing::AddressMetadata{mode4_lookup:Some((lookup,v.memory.read(lookup,1).unwrap()as u8)),..Default::default()};let input=addressing::AddressInput{descriptor:addressing::AddressDescriptor{kind,flags_at_4:0,word_at_6:descflag as u16,word_at_8:8,word_at_10:10,word_at_12:12},mode,native_type:ty,flags,metadata:meta};let p=addressing::select_address(input).unwrap();let actual=p.instructions.iter().flat_map(|j|encoded(j.opcode,&j.words.iter().flat_map(|w|w.to_le_bytes()).collect::<Vec<_>>())).collect();compare(v,0x0fac13f1,&[desc,mode as u32,flags,0,ty as u32],actual,&format!("address kind={kind} mode={mode} ty={ty} flags={flags:x} descriptorflag={descflag}"));n+=1;}}}}}println!("{n} addressing byte+operand+offset/state cases match IR");
let mut n=0;let mut unresolved=0;for d in [3,5,6,8,10,11,12,13,15,16,22]{for s in [3,5,6,8,10,11,12,13,15,16,22]{for f in [0,0x8000]{let mut v=base.clone();v.memory.write_u32(0x20000200,(d as u32)<<16|8).unwrap();v.memory.write_u32(0x20000204,f).unwrap();v.memory.write_u32(0x20000210,0x20000240).unwrap();v.memory.write_u32(0x20000218,0x20000270).unwrap();v.memory.write_u32(0x20000240,(s as u32)<<16|1).unwrap();let i=conversions::ConversionInput{destination_type:d,source_type:s,destination_flags_word:f,metadata:conversions::ResolvedConversionMetadata{destination_slot:Some(0xffff),..Default::default()}};let p=match conversions::select_conversion(i){Ok(p)=>p,Err(_)=>{unresolved+=1;continue;}};let actual=p.instructions.iter().flat_map(|j|encoded(j.opcode,&j.payload)).collect();compare(v,0x0fac0c65,&[0x20000200],actual,&format!("conversion d={d} s={s} flags={f:x}"));n+=1;}}}println!("{n} conversion cases match IR; {unresolved} explicitly unresolved");
let mut n=0;for ty in [3,5,6,8,10,11,12,13]{for value in [0.0f64,1.5,-2.25]{let mut v=base.clone();v.memory.write_u32(0x20000210,0x20000240).unwrap();v.memory.write_u32(0x20000218,0x20000270).unwrap();v.memory.write_u32(0x20000240,(ty as u32)<<16|1).unwrap();v.memory.write(0x20000250,8,value.to_bits()as u128).unwrap();let i=conversions::ConstantConversionInput{source_type:ty,source_ast_id:1,source_flags_word:0,literal_bytes:value.to_le_bytes(),destination_slot:Some(0xffff),interned_string:None};let p=conversions::select_constant_conversion(i).unwrap().unwrap();let actual=p.instructions.iter().flat_map(|j|encoded(j.opcode,&j.payload)).collect();compare(v,0x0fac31c9,&[0x20000200],actual,&format!("constant ty={ty} value={value}"));n+=1;}}println!("{n} constant byte+operand+offset/state cases match IR");}
